class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp_even[s] = max product for a non-empty subsequence with even length and alternating sum s
        # dp_odd[s] = max product for a non-empty subsequence with odd length and alternating sum s
        dp_even = {}
        dp_odd = {}

        for num in nums:
            # Create copies to avoid using the same number multiple times in one step
            new_dp_even = dp_even.copy()
            new_dp_odd = dp_odd.copy()

            # Option 1: Start a new subsequence with just num
            # This subsequence has length 1 (odd), so it goes to dp_odd
            ns = num
            np = num
            if np <= limit:
                if ns not in new_dp_odd or np > new_dp_odd[ns]:
                    new_dp_odd[ns] = np

            # Option 2: Extend an even-length subsequence by adding num
            # Adding num (at even index in subsequence) means: new_sum = s + num
            # The new subsequence has odd length, so goes to dp_odd
            for s, prod in dp_even.items():
                ns = s + num
                np = prod * num
                if np <= limit:
                    if ns not in new_dp_odd or np > new_dp_odd[ns]:
                        new_dp_odd[ns] = np

            # Option 3: Extend an odd-length subsequence by adding num
            # Adding num (at odd index in subsequence) means: new_sum = s - num
            # The new subsequence has even length, so goes to dp_even
            for s, prod in dp_odd.items():
                ns = s - num
                np = prod * num
                if np <= limit:
                    if ns not in new_dp_even or np > new_dp_even[ns]:
                        new_dp_even[ns] = np

            dp_even = new_dp_even
            dp_odd = new_dp_odd

        result = -1
        if k in dp_even:
            result = max(result, dp_even[k])
        if k in dp_odd:
            result = max(result, dp_odd[k])

        return result

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n, s):
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            n_len = len(digits)

            # dp[pos][tight][current_sum][current_prod_mod_s][started]
            # We use memoization with a dictionary or lru_cache
            # Since s is fixed for this call, we can use a closure

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, current_sum, current_prod_mod_s, started):
                if current_sum > s:
                    return 0
                if pos == n_len:
                    # Check if we have a valid number
                    if started and current_sum == s and current_prod_mod_s == 0:
                        return 1
                    else:
                        return 0

                total = 0
                limit = digits[pos] if tight else 9

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    if not started and d == 0:
                        # Leading zero, don't update sum or product
                        new_started = False
                        new_sum = 0
                        new_prod_mod = 0
                    else:
                        new_started = True
                        new_sum = current_sum + d
                        # If new_sum exceeds s, we can skip, but we check at start of next call or here
                        if new_sum > s:
                            continue
                        new_prod_mod = (current_prod_mod_s * d) % s

                    total += dp(pos + 1, new_tight, new_sum, new_prod_mod, new_started)

                return total

            return dp(0, True, 0, 0, False)

        total = 0
        for s in range(1, 82):  # max sum for 10^9 is 9*9=81
            total += count_up_to(r, s) - count_up_to(l - 1, s)

        return total

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute factorials, capped at a value larger than max k (10^15)
        # We cap at 10^15 + 7 to avoid huge number arithmetic, but Python handles big ints fine.
        # Given n <= 100, 100! is huge, but we only care if count >= k.
        INF = 10**16
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(fact[i-1] * i, INF)

        # Separate odd and even numbers
        odds = [x for x in range(1, n + 1) if x % 2 == 1]
        evens = [x for x in range(1, n + 1) if x % 2 == 0]

        # Count initial available odds and evens
        rem_odd = len(odds)
        rem_even = len(evens)

        used = [False] * (n + 1)
        result = []

        # Helper to count required odds/evens for remaining positions
        # Given the last chosen number's parity (last_parity), 
        # count how many odd and even positions are needed for positions i+1 to n-1.
        def count_required(last_parity, positions_left):
            # positions_left is the number of positions to fill after the current one
            # The next position must have parity different from last_parity
            req_odd = 0
            req_even = 0
            # The parity sequence for the remaining positions is fixed and alternating
            # Start with parity different from last_parity
            curr_parity = 1 - last_parity # 0 for even, 1 for odd

            for _ in range(positions_left):
                if curr_parity == 1:
                    req_odd += 1
                else:
                    req_even += 1
                curr_parity = 1 - curr_parity
            return req_odd, req_even

        for i in range(n):
            # Determine candidates for position i
            if i == 0:
                # No previous constraint, try all available numbers in increasing order
                candidates = []
                for x in range(1, n + 1):
                    if not used[x]:
                        candidates.append(x)
            else:
                # Must have different parity from previous
                prev_parity = result[-1] % 2
                candidates = []
                for x in range(1, n + 1):
                    if not used[x] and (x % 2 != prev_parity):
                        candidates.append(x)

            chosen = False
            for c in candidates:
                # Calculate number of valid completions if we pick c
                # Determine remaining odds and evens after picking c
                r_odd = rem_odd
                r_even = rem_even
                if c % 2 == 1:
                    r_odd -= 1
                else:
                    r_even -= 1

                positions_left = n - 1 - i
                if positions_left == 0:
                    count = 1
                else:
                    # Count required odds and evens for the remaining positions
                    # The next position (i+1) must have parity different from c
                    req_odd, req_even = count_required(c % 2, positions_left)

                    if req_odd == r_odd and req_even == r_even:
                        count = fact[r_odd] * fact[r_even]
                    else:
                        count = 0

                if k <= count:
                    # Pick this candidate
                    result.append(c)
                    used[c] = True
                    if c % 2 == 1:
                        rem_odd -= 1
                    else:
                        rem_even -= 1
                    chosen = True
                    break
                else:
                    k -= count

            if not chosen:
                return []

        return result

