import sys

def solve():
    # Set recursion limit higher for deep divide-and-conquer if needed,
    # though iterative or shallow recursion is preferred.
    sys.setrecursionlimit(300000)

    MOD = 998244353

    input = sys.stdin.read
    data = input().split()
    if not data:
        return
    N = int(data[0])

    if N == 1:
        print(1 % MOD)
        return

    # Precompute factorials and inverse factorials
    fact = [1] * (N + 1)
    inv_fact = [1] * (N + 1)

    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N - 1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i + 1) % MOD

    # Compute B_i = 10^{len(i)} for i in 1..N
    # We can compute lengths efficiently
    B = [0] * (N + 1)

    # Precompute powers of 10
    pow10 = [1] * (N + 1)
    curr = 1
    for i in range(1, N + 1):
        curr = (curr * 10) % MOD
        pow10[i] = curr

    for i in range(1, N + 1):
        # Calculate number of digits in i
        # For i in [1, 9], len=1; [10, 99], len=2; etc.
        if i < 10:
            d = 1
        elif i < 100:
            d = 2
        elif i < 1000:
            d = 3
        elif i < 10000:
            d = 4
        elif i < 100000:
            d = 5
        elif i < 1000000:
            d = 6
        elif i < 10000000:
            d = 7
        elif i < 100000000:
            d = 8
        elif i < 1000000000:
            d = 9
        else:
            d = 10

        B[i] = pow10[d]

    # Compute P(x) = product_{i=1}^N (1 + B_i x)
    # Coefficients E_t for t=0..N
    # Use divide and conquer with iterative polynomial multiplication

    def poly_mult(A, B):
        n = len(A)
        m = len(B)
        res = [0] * (n + m - 1)
        for i in range(n):
            if A[i] == 0:
                continue
            val = A[i]
            for j in range(m):
                res[i+j] = (res[i+j] + val * B[j]) % MOD
        return res

    # To avoid recursion depth issues, we can use a queue-based approach
    # or just rely on the fact that log2(200000) is about 18, so recursion is fine.

    def compute_poly(left, right):
        if left == right:
            return [1, B[left]]
        mid = (left + right) // 2
        L = compute_poly(left, mid)
        R = compute_poly(mid + 1, right)
        return poly_mult(L, R)

    E = compute_poly(1, N)
    # E[t] is the t-th elementary symmetric polynomial

    # Compute W_T = sum_{k=1}^N k * E_T^{(k)}
    # E_T^{(k)} = e_T of {B_i}_{i!=k}
    # Recurrence: E_T^{(k)} = E_T - B_k * E_{T-1}^{(k)}

    W = [0] * N  # W[T] for T=0..N-1

    for k in range(1, N + 1):
        bk = B[k]
        # Compute E_T^{(k)} for T=0..N
        # E_0^{(k)} = 1
        # E_T^{(k)} = E[T] - bk * E_{T-1}^{(k)}

        # We only need up to T = N-1 for the final answer, but let's compute up to N
        # to be safe and consistent.

        E_k_prev = 1  # E_0^{(k)}
        # W[0] += k * E_0^{(k)}
        W[0] = (W[0] + k * E_k_prev) % MOD

        for t in range(1, N):
            # E_t^{(k)} = E[t] - bk * E_{t-1}^{(k)}
            E_k_curr = (E[t] - bk * E_k_prev) % MOD
            W[t] = (W[t] + k * E_k_curr) % MOD
            E_k_prev = E_k_curr

    # Total = sum_{T=0}^{N-1} T! (N-1-T)! * W[T]
    ans = 0
    for T in range(N):
        term = fact[T] * fact[N-1-T] % MOD * W[T] % MOD
        ans = (ans + term) % MOD

    print(ans)

solve()

import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        X = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        B = []
        for _ in range(N):
            B.append(int(next(iterator)))

        P = []
        for _ in range(N):
            P.append(int(next(iterator)))

        Q = []
        for _ in range(N):
            Q.append(int(next(iterator)))

    except StopIteration:
        return

    # Convert to 0-indexed
    X -= 1
    P = [p - 1 for p in P]
    Q = [q - 1 for q in Q]

    # Find the red cycle containing X
    red_cycle_nodes = set()
    curr = X
    while curr not in red_cycle_nodes:
        red_cycle_nodes.add(curr)
        curr = P[curr]

    # Find the blue cycle containing X
    blue_cycle_nodes = set()
    curr = X
    while curr not in blue_cycle_nodes:
        blue_cycle_nodes.add(curr)
        curr = Q[curr]

    # Check feasibility:
    # 1. All red balls must be in the red cycle of X
    # 2. All blue balls must be in the blue cycle of X

    # Check red balls
    for i in range(N):
        if A[i] > 0:
            if i not in red_cycle_nodes:
                print(-1)
                return

    # Check blue balls
    for i in range(N):
        if B[i] > 0:
            if i not in blue_cycle_nodes:
                print(-1)
                return

    # Calculate minimum operations
    # Set of boxes to operate on for red balls: red_cycle_nodes - {X}
    # Set of boxes to operate on for blue balls: blue_cycle_nodes - {X}
    # We need the union of these sets.

    boxes_to_operate = set()

    # If there is any red ball in the red cycle, we must operate on all non-X nodes in that cycle
    has_red_ball_in_cycle = False
    for i in red_cycle_nodes:
        if A[i] > 0:
            has_red_ball_in_cycle = True
            break

    if has_red_ball_in_cycle:
        for i in red_cycle_nodes:
            if i != X:
                boxes_to_operate.add(i)

    # If there is any blue ball in the blue cycle, we must operate on all non-X nodes in that cycle
    has_blue_ball_in_cycle = False
    for i in blue_cycle_nodes:
        if B[i] > 0:
            has_blue_ball_in_cycle = True
            break

    if has_blue_ball_in_cycle:
        for i in blue_cycle_nodes:
            if i != X:
                boxes_to_operate.add(i)

    print(len(boxes_to_operate))

if __name__ == '__main__':
    solve()

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Union-Find data structure
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # Path compression
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # Union by rank
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Create a set for O(1) lookup and a mapping from value to index
        num_to_idx = {num: i for i, num in enumerate(nums)}

        # For each number in nums, iterate through its multiples up to threshold
        # If the multiple is also in nums, union the two indices
        for num in nums:
            # Only need to check multiples if num <= threshold
            # Because if num > threshold, then any multiple will be > threshold
            if num > threshold:
                continue
            # Start from 2*num, step by num
            multiple = 2 * num
            while multiple <= threshold:
                if multiple in num_to_idx:
                    idx1 = num_to_idx[num]
                    idx2 = num_to_idx[multiple]
                    union(idx1, idx2)
                multiple += num

        # Count the number of unique roots
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
